const tabs=[...document.querySelectorAll('[role="tab"]')];function activate(tab,focus=false){for(const t of tabs){const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected;}if(focus)tab.focus();}for(const t of tabs){t.addEventListener('click',()=>activate(t));t.addEventListener('keydown',e=>{let i=tabs.indexOf(t);if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();activate(tabs[i],true);});}
let applied=false;document.getElementById('example-apply').addEventListener('click',()=>{applied=!applied;document.getElementById('example-draft').innerHTML=applied?'ある支援先では、作成時間を<strong>30％</strong>削減した。':'作成時間を<strong>50％</strong>削減した。';document.getElementById('example-status').textContent=applied?'取材の数字と対象に合わせた修正例です。':'数値と対象を見比べてください。';document.getElementById('example-apply').textContent=applied?'修正前の文章を見る':'根拠に合わせた修正を見る';});
const slider=document.getElementById('article-count');slider.addEventListener('input',()=>{const count=Number(slider.value);document.getElementById('count-label').textContent=count+'本';document.getElementById('hours-result').textContent=String(Math.round(count*15/60*100)/100);});
